INSERT INTO reading_reorder_items (id, exam_version_id, exam, title, paragraphs, word_count, difficulty, tags, is_published)
VALUES
    ('ri-pte-em-ro-001', 'pte-2026-01', 'PTE', 'The Fishing Industry Has',
     '[{"label": "p1", "text": "The fishing industry has long been hard to monitor. Its global footprint is difficult even to visualize."}, {"label": "p2", "text": "Much fishing takes place unobserved, far from land, and once the boats move on, they leave behind few visible traces of their activity."}, {"label": "p3", "text": "But this week, the journal Science published some remarkable maps that help fill that gap."}, {"label": "p4", "text": "John Amos, president of an organization called Sky Truth, which helped produce them, issued a statement calling the maps &quot;a stunning illustration of the vast scope of exploitation of the ocean."}]'::jsonb, 86, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-002', 'pte-2026-01', 'PTE', 'Hot-Air Balloons Date Back',
     '[{"label": "p1", "text": "Hot-air balloons date back to the year 1783 and within a few months of the first flight a French scientist, Charles, went up two miles in a free balloon."}, {"label": "p2", "text": "Yet there is little resemblance between these crude vehicles and a modern scientific balloon, which has by now become an important tool."}, {"label": "p3", "text": "The main development has been carried out by M. Schwarlschild and his team at Princeton University in the United States in collaboration with the United States Navy."}, {"label": "p4", "text": "The stratoscope''s flights of 1959, concerned mainly with studies of the Sun, were remarkably successful."}]'::jsonb, 93, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-003', 'pte-2026-01', 'PTE', 'Of All The Planets',
     '[{"label": "p1", "text": "Of all the planets in our solar system we are now pretty certain the Earth is the only one on which life can survive."}, {"label": "p2", "text": "Mars is too tiny and poor in oxygen, Venus far too hot, and so is Mercury, and the outer planets have temperatures near absolute zero and hydrogen-dominated atmospheres."}, {"label": "p3", "text": "But other suns, stars as the astronomers call them, are bound to have planets like our own, and as the number of stars in the universe is so vast, this possibility becomes virtual certainty."}, {"label": "p4", "text": "There are one hundred thousand million stars in our own Milky Way alone, and then there are three thousand million other Milky Ways, or Galaxies, in universe."}, {"label": "p5", "text": "So the number of stars that we know exist is estimated at about 300 million."}]'::jsonb, 128, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-004', 'pte-2026-01', 'PTE', 'Economy Is One Powerful',
     '[{"label": "p1", "text": "Economy is one powerful motive for camping, since after the initial outlay upon equipment, or through hiring it, the total expense can be far less than the cost of hotels."}, {"label": "p2", "text": "But, contrary to a popular assumption, it is far from being the only one, or even the greatest."}, {"label": "p3", "text": "The man who manoeuvres carelessly into his five shillings worth of space at one of Europe''s myriad permanent sites may find himself bumping a Bentley."}, {"label": "p4", "text": "More likely, Ford Consul will be hub to hub with Renault or Mecedes, but rarely with bicycles made for two."}, {"label": "p5", "text": "That the equipment of modern camping becomes yearly more sophisticated is an entertaining paradox for the cynic, a brighter promise for the hopeful traveler who has sworn to get away from it all."}]'::jsonb, 126, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-005', 'pte-2026-01', 'PTE', 'The Leggiest Creature On',
     '[{"label": "p1", "text": "The leggiest creature on Earth lives in California: its a three-centimeter-long (1.2 inch) millipede with 750 legs."}, {"label": "p2", "text": "First seen by government scientists in 1928, Illacme plenipes, the acme of plentiful legs, keeps such a low profile that for the rest of the 20th century the species was thought to be extinct."}, {"label": "p3", "text": "Then University of Arizona entomologist Paul Marek spied one near Silicon Valley."}, {"label": "p4", "text": "Marek and colleagues''; new paper, published Wednesday by the journal Zookeys, others the first scientific description of Illacme plenipes, including insights into its strange anatomy."}, {"label": "p5", "text": "For one thing, females have to up to 750 legs and males have more than 550."}]'::jsonb, 104, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-006', 'pte-2026-01', 'PTE', 'An Effective Way To',
     '[{"label": "p1", "text": "An effective way to control joints is with electronic systems that move in response to sensors within the prosthesis, and bionic limbs are already helping disabled people to lead more active lives than ever before."}, {"label": "p2", "text": "When it comes to competitive sport, however, this technology poses a problem as the paralympics currently prohibits prostheses that move artificially."}, {"label": "p3", "text": "This is in order to ensure that the technology only serves to enable the athletes to reach their full physical potential and not to enhance their performance."}, {"label": "p4", "text": "Whether this will change is a point of contention for the industry."}]'::jsonb, 95, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-007', 'pte-2026-01', 'PTE', 'One Explanation Of Dreams',
     '[{"label": "p1", "text": "One explanation of dreams holds that they reflect the ongoing conscious preoccupations of waking life, such as concerns onver health."}, {"label": "p2", "text": "For example, psychologist Gayle Delaney told of a woman who dreamed she was swimming underwater."}, {"label": "p3", "text": "The woman''s eight-year-old son was on her back, his head above water. Her husband was supposed to take pictures, but wasn''t and she was starting to feel she was going to drown."}, {"label": "p4", "text": "To Delaney, the message wa obvious: the woman was \"drowning'' under the responsibilities of child care, and her husband wasn''t \"getting the picture\"."}, {"label": "p5", "text": "In this approach to dreaming, the symbols in a dream do not disguise its true meaning; they convey it."}]'::jsonb, 109, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-008', 'pte-2026-01', 'PTE', 'Thomas Midgley Started His',
     '[{"label": "p1", "text": "Thomas Midgley started his career working on a major problem of the day, called ''engine knock'', where fuel burnt in an uncontrolled explosion."}, {"label": "p2", "text": "At that time additives could reduce the noise but none effectively got rid of it, until Midgley realised that adding lead to petrol solved the problem completely."}, {"label": "p3", "text": "He then turned to refrigerators and was asked to work on safer alternatives to the toxic cooling chemicals used at that time, coming up with CFC gas as a solution."}, {"label": "p4", "text": "These two chemicals gradually ate away at the atmosphere and poisoned millions of people''s health for 50 years until their true impact was finally identified."}]'::jsonb, 105, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-009', 'pte-2026-01', 'PTE', 'Dr Pitsiladis Has Spent',
     '[{"label": "p1", "text": "Dr Pitsiladis has spent years trying to identify why Ethiopian runners from the mountain region are so successful."}, {"label": "p2", "text": "He began by taking DNA samples but found that they all had a very different genetic make-up."}, {"label": "p3", "text": "From this he concluded that there was nothing that could be identified genetically as East African."}, {"label": "p4", "text": "So he then looked at the East African way of life and found that as Children, 68 percent of all top Ethiopian or Kenyan runners ran, rather than walked, to school and back home, from the age of five onwards."}, {"label": "p5", "text": "He tested those children and found that their bodies processed oxygen more efficiently than many adult elite athletes in Britain."}]'::jsonb, 111, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-010', 'pte-2026-01', 'PTE', 'Ideally, The Brand Name',
     '[{"label": "p1", "text": "Ideally, the brand name you choose should be one that doesn''t require translation."}, {"label": "p2", "text": "In other word, it''s the one that''s simple, easy to pronounce and has no particular meaning."}, {"label": "p3", "text": "So a made-up word or compound word can bea good idea."}, {"label": "p4", "text": "However, if your brand name reflects key benefit of your service, such as ''Rental'', then you may want to consider translating it for other markets."}]'::jsonb, 65, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-011', 'pte-2026-01', 'PTE', '60 Years Ago, When',
     '[{"label": "p1", "text": "60 years ago, when businesses did not think of the distribution of goods as a single process, someone had to physically transfer every box each time goods were moved from one transport to another."}, {"label": "p2", "text": "This situation caused delays and created opportunities for damage that were only reduced when the shipping container was invented."}, {"label": "p3", "text": "While this invention promised companies a lot of benefits, there were many difficulties at first."}, {"label": "p4", "text": "The shipping system required many changes and other technical innovations before the containers could be used."}, {"label": "p5", "text": "It was also necessary to build new roads and rail lines, requiring companies to invest millions."}]'::jsonb, 100, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-012', 'pte-2026-01', 'PTE', 'In Some Countries Where',
     '[{"label": "p1", "text": "In some countries where racial prejudice is acute, violence has so come to be taken for granted as a means of solving differences, that it is not even questioned."}, {"label": "p2", "text": "There are countries where the white man imposes his rule by brute force; there are countries where the black man protests by setting fire to cities and by looting and pillaging."}, {"label": "p3", "text": "Important people on both sides, who would in other respects appear to be reasonable men, get up and calmly argue in favor of violence - as if it were a legitimate solution, like any other."}, {"label": "p4", "text": "What is really frightening, what really fills you with despair, is the realization that when it comes to the crunch, we have made no actual progress at all."}, {"label": "p5", "text": "We may wear collars and ties instead of war-paint, but our instincts remain basically unchanged."}]'::jsonb, 138, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-013', 'pte-2026-01', 'PTE', 'When You Travel At',
     '[{"label": "p1", "text": "When you travel at high speeds, the present means nothing: you live mainly in the future because you spend most of your time looking forward to arriving at some other place."}, {"label": "p2", "text": "But actual arrival, when it is achieved, is meaningless. You want to move on again."}, {"label": "p3", "text": "By traveling like this, you suspend all experience; the present ceases to be a reality: you might just as well be dead."}, {"label": "p4", "text": "The traveler on foot, on the other hand, lives constantly in the present."}, {"label": "p5", "text": "For him traveling and arriving are one and the same thing: he arrives somewhere with every step he makes. He experiences the present moment with his eyes, his ears and the whole of his body."}]'::jsonb, 116, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-014', 'pte-2026-01', 'PTE', 'The Past Ages Of',
     '[{"label": "p1", "text": "The past ages of man have all been carefully labeled by anthropologists. Descriptions like: Paleolithic Man,Neolithic Man, etc., neatly sum up whole periods."}, {"label": "p2", "text": "When the time comes for anthropologists to turn their attention to the twentieth century, they will surely choose the label; Legless Man."}, {"label": "p3", "text": "Histories of the time will go something like this; in the twentieth century, people forgot how to use their legs."}, {"label": "p4", "text": "Men and women moved about in cars, buses and trains from a very early age. There were lifts and escalators in all large buildings to prevent people from walking."}, {"label": "p5", "text": "This situation was forced upon earth dwellers of that time because of their extraordinary way of life."}]'::jsonb, 111, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-015', 'pte-2026-01', 'PTE', 'Advertisements Introduce Us To',
     '[{"label": "p1", "text": "Advertisements introduce us to new products or remind us of the existence of ones we already know about."}, {"label": "p2", "text": "Supposing you wanted to buy a washing machine, it is more than likely you would obtain details regarding performance, price, etc., from an advertisement."}, {"label": "p3", "text": "Lots of people pretend that they never read advertisements, but this claim may be seriously doubted."}, {"label": "p4", "text": "It is hardly possible not to read advertisements these days."}]'::jsonb, 68, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-016', 'pte-2026-01', 'PTE', 'Science Is A Dominant',
     '[{"label": "p1", "text": "Science is a dominant theme in our culture."}, {"label": "p2", "text": "Since it touches almost every facet of our life, educated people need at least some acquaintance with its structure and operation."}, {"label": "p3", "text": "They should also have an understanding of the subculture in which scientists live and the kinds of people they are."}, {"label": "p4", "text": "An understanding of general characteristics of science as well as specific scientific concepts is easier to attain if one knows something about the things that excite and frustrate the scientist."}]'::jsonb, 79, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-017', 'pte-2026-01', 'PTE', 'Six Men, Neatly Dressed',
     '[{"label": "p1", "text": "Six men, neatly dressed in white shirts and ties filed into the boardroom of a small Jakarta compact and sat down at a long table."}, {"label": "p2", "text": "But instead of consulting files or hearing reports, they closed their eyes and began to meditate, consulting the spirits of ancient Japanese kings."}, {"label": "p3", "text": "Mysticism touches almost every aspect of life in lndonesia and business is no exception."}, {"label": "p4", "text": "One of the mediators said his weekly meditation sessions are aimed mainly at bringing the peace of mind that makes for good decision-making."}, {"label": "p5", "text": "But the insight gained from mystic communication with spirits of wise kings has also helped boost the profits of his five companies."}]'::jsonb, 107, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-018', 'pte-2026-01', 'PTE', 'Educators Are Seriously Concerned',
     '[{"label": "p1", "text": "Educators are seriously concerned about the high rate of dropouts among the doctor of philosophy candidates and the consequent loss of talent to a nation in need of Ph. D.s."}, {"label": "p2", "text": "Some have placed the dropouts'' loss as high as 50 percent."}, {"label": "p3", "text": "The extent of the loss was, however, largely a matter of expert guessing. Last week a well-rounded study was published."}, {"label": "p4", "text": "It was published. It was based on 22,000 questionnaires sent to former graduate students who were enrolled in 24 universities and it seemed to show many past fears to be groundless."}]'::jsonb, 92, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-019', 'pte-2026-01', 'PTE', 'From The Health Point',
     '[{"label": "p1", "text": "From the health point of view we are living in a marvellous age. We are immunized from birth against many of the most dangerous diseases."}, {"label": "p2", "text": "A large number of once fatal illnesses can now be cured by modern drugs and surgery. It is almost certain that one day remedies will be found for the most stubborn remaining diseases."}, {"label": "p3", "text": "The expectation of life has increased enormously."}, {"label": "p4", "text": "But though the possibility of living a long and happy life is greater than ever befor, every day we witness the incredible slaughter of men, women and children on the roads."}, {"label": "p5", "text": "Man versus the motor-car! It a never-ending battle which man is losing."}]'::jsonb, 108, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-020', 'pte-2026-01', 'PTE', 'Mass Transportation Revised The',
     '[{"label": "p1", "text": "Mass transportation revised the social and economic fabric of the American city in three fundamental ways."}, {"label": "p2", "text": "It catalysed physical expansion, it sorted out people and land used, and it accelerated the inherent instability of urban life. By opening vast areas of unoccupied land for residential expansion, the omnibuses, horse railways, commuter trains, and electric trolleys pulled settled regions outward two to four times more distant form city centres than they were in the pre-modern era."}, {"label": "p3", "text": "In 1850, for example, the borders of Boston lay scarcely two miles from the old business district; by the true of the century the radius extended ten miles."}, {"label": "p4", "text": "Now those who could afford it could live far removed from the old city centre and still commute there for work, shopping, and entertainment."}, {"label": "p5", "text": "The new accessibility of land around the periphery of almost every major city sparked an explosion of real estate development and fuelled what we now know as urban sprawl."}]'::jsonb, 156, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-021', 'pte-2026-01', 'PTE', 'Here''S A Familiar Version',
     '[{"label": "p1", "text": "Here''s a familiar version of the boy-meets-girl situation."}, {"label": "p2", "text": "A young man has at last plucked up courage to invite a dazzling young lady out to dinner. She has accepted his invitation and he is overjoyed."}, {"label": "p3", "text": "He is determined to take her to the best restaurant in town, even if it menas that the will have to live on memories and hopes during the month to come."}, {"label": "p4", "text": "When they get to the restaurant, he discovers that this ethereal creature is on a diet. She mustn''t eat this and she mustn''t that."}, {"label": "p5", "text": "Oh, but of course, she doesn''t want to spoil his enjoyment. Let him by all means eat as much fattening food as he wants: it''s the surest way to an early grave. They spend a truly memorable evening together and never see each other again."}]'::jsonb, 135, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-022', 'pte-2026-01', 'PTE', 'President Arling Has Put',
     '[{"label": "p1", "text": "President Arling has put his long awaited economic restructuring program before the Congress."}, {"label": "p2", "text": "It provides a coordinated program of investment credits, research grants, education reforms, and changes designed to make American industry more competitive."}, {"label": "p3", "text": "This is necessary to reverse economic slide into unemployment, lack of growth, and trade deficits that have plagued the economy for the past six years."}, {"label": "p4", "text": "The most liberal wing of the President''s party has called for stronger and more direct action."}, {"label": "p5", "text": "They want an incomes policy to check inflation federal financing helps rebuild industry behing a wall of protective tariffs."}]'::jsonb, 94, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-023', 'pte-2026-01', 'PTE', 'Although The Top Men',
     '[{"label": "p1", "text": "Although the top men in smuggling business must work together, most of a syndicate''s small fry, especially the mules, know only their immediate contacts. If caught there is little they can give away."}, {"label": "p2", "text": "A mule probably will not even know the name of the person who give him his instructions, nor how to get in touch with him. Usually he even does not know the person to whom he has to make delivery."}, {"label": "p3", "text": "He will be told just to sit tight in a certain hotel or bar until someone contacts him. In this way if he is blown, coming through airport customs. He cannot unwittingly lead agents to the next link in the chain."}, {"label": "p4", "text": "All the persons at the receiving end do is to hang around the airport among the waiting crows, and see that the mule comes through safely, if he does not, he is simply written off as a loss."}, {"label": "p5", "text": "To make identification of mules easier, several syndicates have devised their own \"clubties\" so that a mule wearing one can immediately be picked out."}]'::jsonb, 176, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-024', 'pte-2026-01', 'PTE', 'Television Hasn''T Been With',
     '[{"label": "p1", "text": "Television hasn''t been with us all that long, but we are already beginning to forget what the world was like without it. Before we admitted the one-eyed monster into our homes, we never found it difficult to occupy our spare time. We used to enjoy civilized pleasures. For instance, we used to have hobbies, we used to entertain our friends and be entertained by them, and we used to go outside for our amusements to theatres, cinemas, restaurants and sporting events."}, {"label": "p2", "text": "We even used to read books and listen to music and broadcast talks occasionally, all that belongs to the past. Now all our free time is regulated by the goggle box. We rush home or gulp down our meals to be in time for this or that programme."}, {"label": "p3", "text": "We have even given up sitting at table and having a leisurely evening meal, exchanging the news of the day. A sandwich and a glass of beer will do-anything, providing it don''t interfere with the programme. The monster demands and obtains absolute silence and attention."}, {"label": "p4", "text": "If any member of the family dares to open his mouth during a programme, he is quickly silenced."}, {"label": "p5", "text": "Whole generations are growing up addicted to the telly. Food is left uneaten, homework undone and sleep is lost."}]'::jsonb, 211, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-025', 'pte-2026-01', 'PTE', 'Fishermen''S Knitted Jerseys Have',
     '[{"label": "p1", "text": "Fishermen''s knitted jerseys have always been recognizable in Britain by their colour and their shape."}, {"label": "p2", "text": "Traditionally they are navy blue and they ar basically square in shape, without a curved armhole or inset sleeve."}, {"label": "p3", "text": "The navy jerseys are still a familiar sight on any quay or harbour in the land."}, {"label": "p4", "text": "This continuing popularity cannot just be put down to a fondness for tradition."}, {"label": "p5", "text": "It is mainly due to the quality of the fabric which effectively salt water, sunshine and cold winds."}]'::jsonb, 81, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-026', 'pte-2026-01', 'PTE', 'Despite The Financial Stability',
     '[{"label": "p1", "text": "Despite the financial stability a high salary brings, research has shown that the majority of top earners are not happy their jobs."}, {"label": "p2", "text": "It seems that the lack of psychological reward is the reason for their dissatisfaction."}, {"label": "p3", "text": "However, most of these workers would not consider career alternatives."}, {"label": "p4", "text": "Interestingly, it is not the risk a decrease in salary which prevents this move."}, {"label": "p5", "text": "The fear of criticism from colleagues, friends and family is the main factor that obstructs a change in their employment situation."}]'::jsonb, 81, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-027', 'pte-2026-01', 'PTE', 'A Result Of Not',
     '[{"label": "p1", "text": "A result of not being connected to the electricity grid in rural areas of some countries means people light their homes using kerosene lamps."}, {"label": "p2", "text": "In addition to being fairly costly, these create smoke pollution and carbon emissions."}, {"label": "p3", "text": "Therefore, alternatives are being investigated."}, {"label": "p4", "text": "One such example is a solar panel which could charge an LED lamp to create hours of light each day."}]'::jsonb, 62, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-028', 'pte-2026-01', 'PTE', 'The First International Football',
     '[{"label": "p1", "text": "The first international football match was played in 1872 between England and Scotland, when football, was rarely played anywhere outside Great Britain."}, {"label": "p2", "text": "However, as football increased in popularity, it was admitted to the Olympics Tm in 1900 and 1904, but only as a sideshow and not in the competition medals."}, {"label": "p3", "text": "Only four years later did football become an official competition at the Games. At this stage it was, of course, for amateurs only."}, {"label": "p4", "text": "As an alternative, Sir Thomas Lipton decided to organize an event for professionals. Often described as The First World Cup, it took place in Turin in 1909 and featured the most prestigious professional clubs from ltaly, Germany and Switzerland."}, {"label": "p5", "text": "Ironically, the first tournament was won by an amateur team from the north- cast of England, who had been especially invited after the British Football Association refused to be associated with the competition."}]'::jsonb, 145, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-029', 'pte-2026-01', 'PTE', 'In The Spring Of',
     '[{"label": "p1", "text": "In the spring of 1816, the weather suddenly changed. The unseasonably warm spring turned cold and people were forced indoors by continual rain. The skies darkened and there was no summer."}, {"label": "p2", "text": "A year earlier, a volcano had erupted in indonesia, sending up vast quantities of fine volcanic dust into the atmosphere. Circling the Earth, the dust reflected sunlight back into space."}, {"label": "p3", "text": "The Earth literally darkened temperatures dropped. Throughout western Europe and North America crops failed, and cattle died. A large portion of the world lay under a huge volcanic cloud."}, {"label": "p4", "text": "This, of course, was an extraordinary event In fact, it is considered one of the most catastrophic global events in recorded history. But something like it had happened before, and within living memory."}, {"label": "p5", "text": "Between May and August 1783, two volcanic eruptions had occurred, one in lceland and one in japan. The northern hemisphere had been covered in a \"great fog\"."}]'::jsonb, 150, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-030', 'pte-2026-01', 'PTE', 'It Was George "Beau"',
     '[{"label": "p1", "text": "It was George \"Beau\" Brummell, the champion of simple English style, who started a trend for wearing tight black trousers in the early 1800s."}, {"label": "p2", "text": "By 1817, trousers were shoe-lengh, Popular with the king, they became accepted as standard daywear by 1825 and were worn with a waistcoat and, by day, a frock coat, but with a tailcoat in the evening."}, {"label": "p3", "text": "The favorite patterns for trousers were strong plaids, stripes and checks. The loose straight cut came in about the 1860s, and front creases in the 1880s. By the trun of the century. They had become the common way to dress."}, {"label": "p4", "text": "Jakets didn''t become fashionable for casual wear until the 1850s. The jacket was derived from the short jacket worn by boys and working men, and in the age of mass- production and ready-made suits, its simple style was easier to produce than the tailored coat."}]'::jsonb, 145, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-031', 'pte-2026-01', 'PTE', 'Until The 19Th Century',
     '[{"label": "p1", "text": "Until the 19th century, workers were given little or no protection. Child labor was common, as were long hours worked in unsafe conditions for minimal pay."}, {"label": "p2", "text": "In the late 18th century, groups of skilled workers began to control the hiring of apprentices, and bargained with employers for better working conditions, but as the movement grew, these trade unions tried to find ways of creating an alliance among themselves."}, {"label": "p3", "text": "The first meeting of the Trades Union Congress look place in Manchester, at which-four delegates represented well over a hundred thousand trade union members."}, {"label": "p4", "text": "Trade unions were legalized in an Act of 1871, and by the end of the century more than one and a half million workers were members. Conditions for workers slowly improved over the years, but it wasn''t until 1974 that legislation covering the health and safety of all employees was introduced."}]'::jsonb, 143, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-032', 'pte-2026-01', 'PTE', 'For Each Of The',
     '[{"label": "p1", "text": "For each of the three major counties of western Europe-Britain, France, and Germany- the closing decades of the 18 th century were years of increasing economic prosperity, and the pace of economic development in Britain far outdid that the others."}, {"label": "p2", "text": "At the turn o the 19 th century, however, only a relatively small sector of the British economy had been directly affected by the industrial Revolution."}, {"label": "p3", "text": "Even two decades later, the picture was little different, except that cotton had become the country''s leading manufacturing industry. It was not until the middle of the century that it could be properly described as an industrial society."}, {"label": "p4", "text": "It would be a mistake to call the other two countries underdeveloped - in terms cultural achievement, especially literature, art, and philosophy, they outstripped Britain - but they legged behind in terms of economic development."}]'::jsonb, 139, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-033', 'pte-2026-01', 'PTE', 'In 1679, What Became',
     '[{"label": "p1", "text": "In 1679, what became known as the first Exclusionist Parliament passed at least one useful piece of legislation: on the day parliament was suspended, the King gave his assent to a Habeas Corpus Act."}, {"label": "p2", "text": "Habeas Corpus, a law by which a prisoner could demand to be brought before the courts and have his case heard, was a well-established right in England but the authorities had found a number of ways of getting round its use where political prisoners were concerned."}, {"label": "p3", "text": "James Harrington, the philosopher, is a good example, When his sisters applied for habeas corpus. He was taken from the Tower of London to a barren island where habeas corpus could not be imposed."}, {"label": "p4", "text": "The new act put a stop to such abuses and deprived the executive powers it might have used to support oppressive and arbitrary government."}]'::jsonb, 138, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-034', 'pte-2026-01', 'PTE', 'False Memories Are Constructed',
     '[{"label": "p1", "text": "False memories are constructed by combining actual memories with the content of suggestions received from others."}, {"label": "p2", "text": "During the process, individuals may forget the source of the information."}, {"label": "p3", "text": "This is a classic example of source confusion, in which the content and the source become dissociated."}, {"label": "p4", "text": "Of course, because we can implant false childhood memories in some individuals in no way implies that all memories that arise after suggestion are necessarily false."}, {"label": "p5", "text": "Put another way, although experimental work on the creation of false memories may raise doubt about the validity of long-buried memories. Such as repeated trauma, it in no way disproves them."}]'::jsonb, 101, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-035', 'pte-2026-01', 'PTE', 'Normally In Delhi, Septemer',
     '[{"label": "p1", "text": "Normally in Delhi, septemer is a month of almost equatorial fertility and and the land seems refreshed and newly-washed."}, {"label": "p2", "text": "But in the year of our arrival, after a parching summer, the rains had lasted for only three Weeks."}, {"label": "p3", "text": "As a result dust was everywhere and the city''s trees and flowers all looked as if they had been lightly sprinkled with talcum powder."}, {"label": "p4", "text": "Nevertheless the air was still sticky with damp-heat, and it was in a cloud of perspiration that we began to unpack."}]'::jsonb, 83, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-036', 'pte-2026-01', 'PTE', 'Fossilized Fish Remains Have',
     '[{"label": "p1", "text": "Fossilized fish remains have been found high up on the slopes of Everest proving that world''s highest mountain once lay at the bottom of the sea. How did this happen?"}, {"label": "p2", "text": "About 200 million years ago, the India subcontinent broke away from a vast southern super- continent called Gondwanaland. It drifted northeast across the sea and collided with the Asian Landmass. These two huge landmasses buckled, rather like cars in a head-on collision, and rose up to from the world''s tallest mountain."}, {"label": "p3", "text": "One of the Tibetan names for this mountain translates as\" Mountain So High That No Bird Can Fly Over It\". It was first measured in 1852 and was called Peak XV until 1865, when it was named after the British Surveyor of India, Sir George Everest."}, {"label": "p4", "text": "Mapping the Himalayas and Everest wasn''t easy. Foreigners were not welcome, so Himalayan traders were recruited to infiltrate the area and gather enough information to allow accurate maps to be made."}]'::jsonb, 158, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-037', 'pte-2026-01', 'PTE', 'The Town Of Liberal',
     '[{"label": "p1", "text": "The town of Liberal is said to have been named for an early settler famous among travellers for being free with drinking water."}, {"label": "p2", "text": "Liberal is conservative in a moderate Midwestern kind of way which is changing feast due to big National Beef Packing plant which relies on Hispanic migrants, and four- fifths of the children in Liberal''s public-school system are Hispanic."}, {"label": "p3", "text": "This should make the town receptive to Democrats, but Mr. Trump easily won the county of which it forms a part."}, {"label": "p4", "text": "Liberal''s mayor, Joe Denoyer, who was raised in a Democratic family near Chicago and moved to Liberal in search of work."}, {"label": "p5", "text": "Mr. denoyer voted for Mr. Trump by being impressed by his promise, though he thinks it unlikely that the president will keep his promises."}]'::jsonb, 127, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-038', 'pte-2026-01', 'PTE', 'A Recent Research Has',
     '[{"label": "p1", "text": "A recent research has revealed that more than 60,000 species of trees are available globally."}, {"label": "p2", "text": "The BCGI (Botanical Gardens Conservation International), A charity that compiled the list of trees on the basis of data gathered from its network of 500 members organizations."}, {"label": "p3", "text": "The researchers claim to have collected information over a period of two years from sources including over 500 published contents and 80 experts in the BCGI''s network."}, {"label": "p4", "text": "The data will be kept updated with the discovery of new species or the extinction of some, said the researchers."}, {"label": "p5", "text": "All the data required for the world''s trees is now available in one database, thanks to Global tree search."}]'::jsonb, 108, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-039', 'pte-2026-01', 'PTE', 'Sometime About A Million',
     '[{"label": "p1", "text": "Sometime about a million and a half years ago, some forgotten genius of the hominid world did an unexpected thing."}, {"label": "p2", "text": "He (or very possibly she) took one stone and carefully used it to shape another."}, {"label": "p3", "text": "The result was a simple teardrop-shaped hand-axe, but it was the world''s first piece of advanced technology."}, {"label": "p4", "text": "It was so superior to existing tools that soon others were following the inventor''s lead and making hand-axes of their own."}, {"label": "p5", "text": "Eventually whole societies existed that seemed to do little else."}]'::jsonb, 83, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-040', 'pte-2026-01', 'PTE', 'Railway, In The 1',
     '[{"label": "p1", "text": "Railway, in the 1 840s, intrigue has swirled around the Box Tunnel, a long steep bypass near Bath, England."}, {"label": "p2", "text": "The question was this: did the railway''s creator, Islamabad Kingdom Brunel, really have the tunnel carved in such a way that when the sun rose on his birthday-April 9 th -it would be flooded with light?"}, {"label": "p3", "text": "This past Sunday, April 9th, the railway''s current engineers decide to test the rumour once and for all. They weren''t disappointed."}, {"label": "p4", "text": "\"When you look from the east portal, the cutting provides a lovely V-shape,\" communications manager Paul Gentleman told the Guardian."}, {"label": "p5", "text": "While the west side''s view wasn''t quite so impressive, the engineers generously chalked that to centuries of dirt and grime."}]'::jsonb, 116, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-041', 'pte-2026-01', 'PTE', 'Jean Briggs Has Worked',
     '[{"label": "p1", "text": "Jean Briggs has worked with the lnuit of the Canadian Arctic and has described how, within these communities, growing up is largely seen as a process of acquiring thought, reason and understanding (known in lnuit as ihuman)."}, {"label": "p2", "text": "Young children don''t possess these qualities and are easily angered, cry frequently and are incapable of understanding the external difficulties facing the community, such as shortages of food."}, {"label": "p3", "text": "Because they can''t be reasoned with, and don''t understand parents treat them with a great deal of tolerance and leniency."}, {"label": "p4", "text": "It only when they are older and begging to acquire thought that parents attempt to teach them or discipline them."}]'::jsonb, 105, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-042', 'pte-2026-01', 'PTE', 'Earlier This Year, Researchers',
     '[{"label": "p1", "text": "Earlier this year, researchers from Duke University went to Gabon to monitor that country''s dwindling elephant population. They took along three drones, which they planned to use to count the elephants, follow their herds, and map their migrations."}, {"label": "p2", "text": "Only things didn''t exactly go as planned."}, {"label": "p3", "text": "The elephants noticed the drones, which hovered anywhere from 25 feet to 300 feet above them. And it wasn''t just that the elephants noticed them; in many cases, the elephants were clearly agitated. Some of them took off running. In at least one case, an elephant used her trunk to lurk mud in the drone''s direction."}, {"label": "p4", "text": "The elephants reacted so strongly, the researchers believe, because drones, it turns out, sound a lot like bees. And elephants do not like bees. At all."}]'::jsonb, 127, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-043', 'pte-2026-01', 'PTE', 'Citizens Commonly Identify With',
     '[{"label": "p1", "text": "Citizens commonly identify with their nation in the context of major sporting events: imagining the nation is easier when there is a national team playing another nation (Hobsbawm, 1990)."}, {"label": "p2", "text": "Rugby in Wales is a particularly strong example of this phenomenon, being perhaps the main thing that unites people in Wales."}, {"label": "p3", "text": "In many ways rugby in Wales defines what Wales is and what people in Wales share."}, {"label": "p4", "text": "From outside Wales, too, it is the rugby that commonly defines the nation - with the sport providing both widespread interest and one of the few positive associations of outsides'' perceptions of Wales."}]'::jsonb, 99, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-044', 'pte-2026-01', 'PTE', 'Over The Years, I',
     '[{"label": "p1", "text": "Over the years, I have had the opportunities to observe and understand the thought processes behind the ads that have been flooding both the print and the TV media."}, {"label": "p2", "text": "Although there is a huge shift in the quality of ads that we come across on a daily basis- thanks essentially to improvement in technology-I somehow can''t help but feel that the quality of communication of the message has become diluted."}, {"label": "p3", "text": "There is an increasing attempt by most companies to be seen as cool and funky."}, {"label": "p4", "text": "Another reason could be the burgeoning number of companies, which means an exponential increase in the number of ads that are being made."}, {"label": "p5", "text": "Proportionally, the number of ads that lack in quality, has gone up exponentially as well!!"}]'::jsonb, 123, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-045', 'pte-2026-01', 'PTE', 'The Camel Is Called',
     '[{"label": "p1", "text": "The camel is called ''the ship of the desert'' and there is a good reason for it."}, {"label": "p2", "text": "Where other animals would die for lack of food and water, the camel gets along nicely because it carries its food and water with it."}, {"label": "p3", "text": "For days before it starts on a journey, a camel does nothing but eat and drink."}, {"label": "p4", "text": "It eats so much that a hump of fat may be weighing as much as 100 pounds, rises on its back."}, {"label": "p5", "text": "So the camel''s hump is a storage place for fat, which the camel''s body will use up during the journey."}]'::jsonb, 99, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-046', 'pte-2026-01', 'PTE', 'A Greedy Fox Stealthily',
     '[{"label": "p1", "text": "A greedy fox stealthily entered a garden to eat the grapes."}, {"label": "p2", "text": "But its tail was cut down by a trap when it tried to escape from the trap."}, {"label": "p3", "text": "It worried because all other foxes would mock at its lost tall. Hence it planned a trick."}, {"label": "p4", "text": "When all foxes ridiculed it and said, \"I have cut down the tail myself because it was a great hindrance."}, {"label": "p5", "text": "Now I am free and happy without my tail."}]'::jsonb, 74, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-047', 'pte-2026-01', 'PTE', 'Intelligence Can Be Measured',
     '[{"label": "p1", "text": "Intelligence can be measured by tests."}, {"label": "p2", "text": "Benet developed the first set of such tests in the early 1990s to find out which children in school needed special attention."}, {"label": "p3", "text": "Since then, intelligence tests have been mostly used to separate dull children in school from average or bright children, so that special education can be provided to the dull."}, {"label": "p4", "text": "Intelligence is expressed as intelligence quotient, and tests developed to indicate what an average child of a certain age can do…What a five-year-old can answer, but a four-year- old cannot, for instance."}, {"label": "p5", "text": "In other words, intelligence tests give us a norm for each age."}]'::jsonb, 101, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-048', 'pte-2026-01', 'PTE', 'Most Computer Users Develop',
     '[{"label": "p1", "text": "Most computer users develop disorders because they ignore warnings like tingling fingers, a numb hand or a sore shoulder."}, {"label": "p2", "text": "They keep pointing and dragging until tendons chafe and scar tissue forms, along with bad habits that are almost impossible to change."}, {"label": "p3", "text": "Thus begins the search for relief: painkillers, ice, yoga, herbs, even surgery."}, {"label": "p4", "text": "But cures are elusive because repetitive stress injuries present a bag of pills that often defy easy diagnosis."}]'::jsonb, 71, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-049', 'pte-2026-01', 'PTE', 'The Japanese Are Very',
     '[{"label": "p1", "text": "The Japanese are very efficient and such concepts as \"just in time\" are a witness to their efficiency."}, {"label": "p2", "text": "But they reach efficiency in a different way than American businesses."}, {"label": "p3", "text": "They reach efficiency through the route of effectiveness."}, {"label": "p4", "text": "The main difference is that efficiency is a ration and effectiveness is not."}]'::jsonb, 50, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-050', 'pte-2026-01', 'PTE', 'When The Activity Of',
     '[{"label": "p1", "text": "When the activity of the sun changes, it has direct effects on the earth."}, {"label": "p2", "text": "For example, when the sun is relatively inactive, the amount of a type of carbon called - 14 increases in the earth''s atmosphere."}, {"label": "p3", "text": "Because carbon in the air is absorbed by trees, carbon - 14 levels in tree rings actually reflect solar activity and unusual solar events in the past."}, {"label": "p4", "text": "The researchers took advantage of such a phenomenon by analyzing a specimen from a bristlecone pine tree, a species that can live for thousands of years, to look back deep into the history of the sun."}]'::jsonb, 100, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-051', 'pte-2026-01', 'PTE', 'Plants Are One Of',
     '[{"label": "p1", "text": "Plants are one of the two groups into which all living things were traditionally divided; the other is animals."}, {"label": "p2", "text": "The division goes back at least as far as Aristotle (384 BC - 322 B"}, {"label": "p3", "text": ", who distinguished between plants."}, {"label": "p4", "text": "Much later, when Linnaeus (1707-1778) created the basis of the modern system of scientific classification, these two groups became the kingdoms Vegetabilia and Animalia."}]'::jsonb, 63, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-052', 'pte-2026-01', 'PTE', 'Humans Need Rest To',
     '[{"label": "p1", "text": "Humans need rest to recover from tiredness."}, {"label": "p2", "text": "The average sleep requirement is between seven and nine hours per day for an adult and nine to ten hours per day for a child; elderly people usually sleep for six to seven hours."}, {"label": "p3", "text": "Having less sleep than this is common among humans, even though sleep deprivation can have negative health effects."}, {"label": "p4", "text": "A sustained restriction of adult sleep to four hours per day has been shown to correlate with changes in physiology and mental state, including reduced memory, fatigue, aggression, and bodily discomfort."}]'::jsonb, 90, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-053', 'pte-2026-01', 'PTE', 'The Ideological Orientation, However',
     '[{"label": "p1", "text": "The ideological orientation, however, is not only confined to the formulation of the goals of social change, but also extends to the specific form the sociological categories should have to analyzechange."}, {"label": "p2", "text": "To achieve this goal is a case for the development of a particularistic or typical Indian sociology is made."}, {"label": "p3", "text": "Its proponents admit, however, that sociological explanations involve some form of intellection which is universalistic, call it ''sociological apperception'', ''empathy'', or ''sociological imagination'', but simultaneously they also hold that explanation of specific forms of change in the cultural context of a nation requires delineation of conceptual categories applicable only to that particular culture."}, {"label": "p4", "text": "Hence, they claim there should be an Indian sociology distinct from sociology in the West or in other parts of the world."}, {"label": "p5", "text": "This particularism of some Indian sociologists introduces yet another ideological element in the analysis of change."}]'::jsonb, 141, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-054', 'pte-2026-01', 'PTE', 'An Important Feature Of',
     '[{"label": "p1", "text": "An important feature of modern education is that it encourages cooperation rather than competition."}, {"label": "p2", "text": "Some people think that in this cooperative endeavour, the intelligent students stand to lose since they cannot make the best of their talents, but this seems to be a vague fear."}, {"label": "p3", "text": "In fact, personality development can only take place by working in co-operation with others and not in isolation."}, {"label": "p4", "text": "It is only when a child works within a group that his qualities of leadership will manifest themselves."}, {"label": "p5", "text": "His character will only be shaped by coming into contact with others and by working with them."}]'::jsonb, 98, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-055', 'pte-2026-01', 'PTE', 'Blind Embossing Does Not',
     '[{"label": "p1", "text": "Blind embossing does not include the use of ink or foil to highlight the embossed area."}, {"label": "p2", "text": "The change in the dimensional appearance of the material is the only noticeable difference resulting from the embossing."}, {"label": "p3", "text": "The blind embossing process provides a clean and distinctive or subtle image on paper stock."}, {"label": "p4", "text": "It is best used to create a subtle impression or low level of attention to the piece, yet provide some slight form of differentiation for the finished work."}]'::jsonb, 77, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-056', 'pte-2026-01', 'PTE', 'When Nasa Tested The',
     '[{"label": "p1", "text": "When NASA tested the pouch, they found it definitely contained lunar dust, a fine grey powder resembling graphite."}, {"label": "p2", "text": "In fact, it contained some of the very first moon dust ever collected, by the Apollo 11 astronaut Neil Armstrong back in July 1969."}, {"label": "p3", "text": "After Armstrong and fellow astronaut Edwin \"Buzz\" Aldrin returned to Earth, the bag containing the lunar sample had somehow been misplaced and forgotten."}, {"label": "p4", "text": "It wasn''t included with the hundreds of Apollo 11 artifacts Johnson Space Center sent to the Smithsonian Air & Space Museum."}]'::jsonb, 86, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-057', 'pte-2026-01', 'PTE', 'The Most Common Way',
     '[{"label": "p1", "text": "The most common way of childbirth is a vaginal delivery."}, {"label": "p2", "text": "It involves three stages of labour: the shortening and opening of the cervix, descent and birth of the baby, and the delivery of the placenta."}, {"label": "p3", "text": "The first stage typically lasts twelve to nineteen hours, the second stage twenty minutes to two hours, and the third stage five to thirty minutes."}, {"label": "p4", "text": "The first stage begins with crampy abdominal or back pains that last around half a minute and occur every ten to thirty minutes."}, {"label": "p5", "text": "A number of methods can help with pain such as relaxation techniques, opioids, and spinal blocks."}]'::jsonb, 99, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-058', 'pte-2026-01', 'PTE', 'We''Re All Familiar With',
     '[{"label": "p1", "text": "We''re all familiar with superheroes defeating villains in comic books and movies, but there are real people with superpowers that walk among us every day."}, {"label": "p2", "text": "These people, known as HIV Controllers, are able to successfully fight the HIV virus in their own bodies, while living normal, health lives."}, {"label": "p3", "text": "The HIV Controller power is a very rare one. Only one is 300 people have this ability, but we all might have this power in the near future."}, {"label": "p4", "text": "Because, by studying HIV Controllers, The Immunity Project is attempting to develop a vaccine that will protect non-infected people from the deadly disease."}]'::jsonb, 99, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-059', 'pte-2026-01', 'PTE', 'On March 1St, 1950',
     '[{"label": "p1", "text": "On March 1st, 1950, a natural gas explosion in Nebraska completely destroyed a church."}, {"label": "p2", "text": "Choir practice at the West Side Baptist Church usually started at 7:20 p.m"}, {"label": "p3", "text": "The church exploded at 7:25, but not a single person was killed or injured."}, {"label": "p4", "text": "The choir members usually arrived early, but on that day, every single one of them was late."}]'::jsonb, 58, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-060', 'pte-2026-01', 'PTE', 'While Pharmaceutical Companies Do',
     '[{"label": "p1", "text": "While pharmaceutical companies do a lot of good for the world, may of their choice are influenced by profits over people."}, {"label": "p2", "text": "For example, in 2012, pharmaceutical companies made 83.9 billion dollars in profit."}, {"label": "p3", "text": "Much of these profits were made from drugs for heart disease, high blood pressure, and depression."}, {"label": "p4", "text": "These are the kind of problems that are life-long problems, which means life-long medication and life-long profits."}]'::jsonb, 66, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-061', 'pte-2026-01', 'PTE', 'In A Recent Research',
     '[{"label": "p1", "text": "In a recent research study at the Max Planck Institute, participants were given a choice to press a button with either their left or right hand."}, {"label": "p2", "text": "The only rule was they needed to record when they made the choice."}, {"label": "p3", "text": "During this experiment, all the participants were have their brains scanned with an MRI."}, {"label": "p4", "text": "Looking at these brain scans, the researchers were able to clearly see different brain patterns for participants who chose the left button and participants who chose the right button."}]'::jsonb, 82, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-062', 'pte-2026-01', 'PTE', 'Our Bodies Are Crawling',
     '[{"label": "p1", "text": "Our bodies are crawling inside and out with microbes."}, {"label": "p2", "text": "In fact the number of microbial cells on and in your right now outnumber your human cells 10 to 1. And the biggest concentration of these microbes is in your gut."}, {"label": "p3", "text": "Scientists are starting to think there could be a direct connection between our guts and our minds."}, {"label": "p4", "text": "We have long known that microbes can help our bodies fight infections, thus, an experiment will be conducted among 45 participants to establish that direct connection."}]'::jsonb, 83, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-063', 'pte-2026-01', 'PTE', 'Are You Superstitious? Most',
     '[{"label": "p1", "text": "Are you superstitious? Most people would say no, but in fact, many of us do make choices in our live that are completely irrational. Now consider following the examples."}, {"label": "p2", "text": "In the USA, Friday, the 13th is thought to be so unlucky that 10,000 fewer people fly on this day."}, {"label": "p3", "text": "And airlines make much less money than other Fridays, because fewer people are travelling."}, {"label": "p4", "text": "Also, some elevators in the USA even skip the 13th floor, moving from the 12th floor to the 14th floor."}, {"label": "p5", "text": "Similarly in Japan and China, people are superstitious about the number 4, and buildings sometimes lack a 4th floor. Thus list of these kind of stories goes on and on."}]'::jsonb, 113, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-064', 'pte-2026-01', 'PTE', 'Fear Can Be A',
     '[{"label": "p1", "text": "Fear can be a useful emotion when it helps us escape physically pain and danger, but social fear almost always holds us back from success."}, {"label": "p2", "text": "Fear of rejection can stop us from going after job of our dreams, for example. Fear of rejection can stop us from meeting the man or woman of our dreams. And fear of rejection can also stop us from using our English."}, {"label": "p3", "text": "The next time you see someone who you''d like to speak English with in a coffee shop or on the street, challenge yourself to do it."}, {"label": "p4", "text": "The worse thing that will happen is they''ll say no, and you''ll gain some experience on how to gracefully handle rejection. Be confident, don''t be shy."}]'::jsonb, 119, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-065', 'pte-2026-01', 'PTE', 'Jay Jiang Is The',
     '[{"label": "p1", "text": "Jay Jiang is the founder of a small computer application company called Hooplas. His company is new and he recently had a big setback when he got rejected by an investor."}, {"label": "p2", "text": "He was traumatized by this rejection. He had a sinking feeling in his stomach and was angry and insecure."}, {"label": "p3", "text": "Jiang wanted to give up on his company, but instead he decided he needed to build his confidence."}, {"label": "p4", "text": "If he was going to be successful again, he needed to get comfortable with failure and rejection. He needed rejection therapy."}]'::jsonb, 89, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-066', 'pte-2026-01', 'PTE', 'Stephen Collins, A Researcher',
     '[{"label": "p1", "text": "Stephen Collins, a researcher from McMaster University, used mice to investigate the brain-gut connection."}, {"label": "p2", "text": "He took the dominant microbes found in sky mice and introduced the into the guts of fearless mice."}, {"label": "p3", "text": "He also tried this experiment in reverse, by introducing the microbes from the fearless mice into the guts of the sky mice."}, {"label": "p4", "text": "In both cases, he found that the personality and behaviour of the mice changed."}, {"label": "p5", "text": "The previously sky mice became more active and the previously tearless mice became more quiet and shy."}]'::jsonb, 85, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE),
    ('ri-pte-em-ro-067', 'pte-2026-01', 'PTE', 'According To New Research',
     '[{"label": "p1", "text": "According to new research, irrational superstitions might not be a bad thing. In one psychology experiment, people were tested on their golfing skills."}, {"label": "p2", "text": "Half of the people were randomly selected and told that their balls were lucky. These people scored 35% better than those given \"normal\" balls."}, {"label": "p3", "text": "Of course, both the \"lucky\" balls and the \"normal\" balls were exactly the same."}, {"label": "p4", "text": "The researchers believe that using a \"lucky\" ball, made people feel more confident, which led to better performance."}]'::jsonb, 79, 'medium', ARRAY['PTE', 'Exam Memories', 'Reorder Paragraph']::text[], TRUE)
ON CONFLICT (id) DO NOTHING;

